-- =====================================================
-- 2. STORAGE POLICIES FOR PUBLIC BUCKETS
-- =====================================================

-- Landing assets policies (public read, admin write)
CREATE POLICY "landing_assets_public_read"
ON storage.objects FOR SELECT
TO anon, authenticated
USING (bucket_id = 'landing-assets');

CREATE POLICY "landing_assets_admin_write"
ON storage.objects FOR INSERT
TO authenticated
WITH CHECK (
    bucket_id = 'landing-assets' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin'
);

CREATE POLICY "landing_assets_admin_update"
ON storage.objects FOR UPDATE
TO authenticated
USING (
    bucket_id = 'landing-assets' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin'
);

CREATE POLICY "landing_assets_admin_delete"
ON storage.objects FOR DELETE
TO authenticated
USING (
    bucket_id = 'landing-assets' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin'
);

