-- =====================================================
-- 3. STORAGE POLICIES FOR PRIVATE BUCKETS
-- =====================================================

-- Attachments policies (staff can manage, clients can view their own)
CREATE POLICY "attachments_staff_all"
ON storage.objects FOR ALL
TO authenticated
USING (
    bucket_id = 'attachments' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') IN ('admin', 'vet', 'assistant', 'receptionist')
)
WITH CHECK (
    bucket_id = 'attachments' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') IN ('admin', 'vet', 'assistant', 'receptionist')
);

CREATE POLICY "attachments_client_read_own"
ON storage.objects FOR SELECT
TO authenticated
USING (
    bucket_id = 'attachments' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'client' AND
    (storage.foldername(name))[1] = auth.uid()::text
);

-- Patient images policies (staff can manage, clients can view their pets)
CREATE POLICY "patient_images_staff_all"
ON storage.objects FOR ALL
TO authenticated
USING (
    bucket_id = 'patient-images' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') IN ('admin', 'vet', 'assistant', 'receptionist')
)
WITH CHECK (
    bucket_id = 'patient-images' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') IN ('admin', 'vet', 'assistant', 'receptionist')
);

CREATE POLICY "patient_images_client_read_own"
ON storage.objects FOR SELECT
TO authenticated
USING (
    bucket_id = 'patient-images' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'client' AND
    EXISTS (
        SELECT 1 FROM patients p
        JOIN clients c ON p.client_id = c.id
        WHERE c.user_id = auth.uid()
        AND (storage.foldername(name))[1] = p.id::text
    )
);

-- =====================================================
-- 4. HELPER FUNCTIONS FOR STORAGE
-- =====================================================

-- Function to get file extension
CREATE OR REPLACE FUNCTION storage.extension(name text)
RETURNS text AS $
BEGIN
    RETURN lower(substring(name from '\.([^.]*)$'));
END;
$ LANGUAGE plpgsql;

-- Function to get folder name from path
CREATE OR REPLACE FUNCTION storage.foldername(name text)
RETURNS text[] AS $
BEGIN
    RETURN string_to_array(name, '/');
END;
$ LANGUAGE plpgsql;

-- =====================================================
-- 5. STORAGE VALIDATION FUNCTIONS
-- =====================================================

-- Function to validate image file types
CREATE OR REPLACE FUNCTION storage.is_image(name text)
RETURNS boolean AS $
BEGIN
    RETURN storage.extension(name) IN ('jpg', 'jpeg', 'png', 'webp', 'gif', 'svg');
END;
$ LANGUAGE plpgsql;

-- Function to validate file size (in bytes)
CREATE OR REPLACE FUNCTION storage.is_valid_size(size bigint, max_size bigint)
RETURNS boolean AS $
BEGIN
    RETURN size <= max_size;
END;
$ LANGUAGE plpgsql;

-- =====================================================
-- 6. ENHANCED STORAGE POLICIES WITH VALIDATION
-- =====================================================

-- Enhanced landing assets policy with file type validation
DROP POLICY IF EXISTS "landing_assets_admin_write" ON storage.objects;
CREATE POLICY "landing_assets_admin_write"
ON storage.objects FOR INSERT
TO authenticated
WITH CHECK (
    bucket_id = 'landing-assets' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin' AND
    storage.is_image(name) AND
    storage.is_valid_size(metadata->>'size'::bigint, 10485760)
);

-- Enhanced branding assets policy with file type validation
DROP POLICY IF EXISTS "branding_assets_admin_write" ON storage.objects;
CREATE POLICY "branding_assets_admin_write"
ON storage.objects FOR INSERT
TO authenticated
WITH CHECK (
    bucket_id = 'branding-assets' AND 
    (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin' AND
    storage.is_image(name) AND
    storage.is_valid_size(metadata->>'size'::bigint, 5242880)
);

